function CaseList({ cases, open }: { cases: M.Case[]; open: (id: string) => void }) {
  const labels = useContext(RuleLabels);
  const [status, setStatus] = useState(''), [type, setType] = useState(''), [group, setGroup] = useState(''), [from, setFrom] = useState(''), [to, setTo] = useState('');
  const caseStatus = (c: M.Case) => c.state === 'submitted' ? M.work(c).open.length ? 'progress' : 'ready' : c.state;
  const rows = cases.filter(c => (!status || caseStatus(c) === status) && (!type || c.facts.caseType === type) && (!group || c.facts.businessGroup === group) && (!from || c.facts.lastDay >= from) && (!to || c.facts.lastDay <= to));
  return <><div className="v9-panel v9-filters"><Field label="Business Group"><select value={group} onChange={event=>setGroup(event.target.value)}><option value="">All Business Groups</option>{[...new Set(cases.map(c=>c.facts.businessGroup).filter(Boolean))].map(id=><option key={id} value={id}>{labels?.businessGroup?.[id]??'Unmapped Business Group'}</option>)}</select></Field><Field label="Last working day from"><OnboardingDateInput label="Last working day from" value={from} onChange={setFrom}/></Field><Field label="Last working day to"><OnboardingDateInput label="Last working day to" value={to} onChange={setTo}/></Field><Field label="Case type"><select value={type} onChange={e => setType(e.target.value)}><option value="">All case types</option>{['Resignation', 'Termination', 'Contract end', 'Retirement', 'Non-confirmation'].map(t => <option key={t}>{t}</option>)}</select></Field><Field label="Status"><select value={status} onChange={e => setStatus(e.target.value)}><option value="">All statuses</option>{[['pending','Pending submission'],['progress','In progress'],['ready','Ready for clearance'],['cleared','Cleared'],['cancelled','Cancelled']].map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></Field></div><div className="v9-muted">{rows.length} cases</div><div className="v9-table-scroll"><table className="v9-table"><thead><tr>{['Full name', 'Business Group', 'Case type', 'Last working day', 'Offboarding case ID', 'Progress', 'Status'].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(c => { const p = M.work(c); return <tr key={c.id}><td><button type="button" className="v9-link" onClick={() => open(c.id)}>{c.facts.name}</button><div className="v9-muted">{c.facts.employeeNo}</div></td><td>{labels?.businessGroup?.[c.facts.businessGroup] ?? (c.facts.businessGroup ? 'Unmapped Business Group' : '—')}</td><td>{c.facts.caseType}</td><td>{date(c.facts.lastDay)}</td><td>{c.number}</td><td><progress className="v9-progress" value={p.done} max={p.total || 1} aria-label={`${c.facts.name} progress`}/><div className="v9-muted">{p.percent}% · {p.done} of {p.total} done</div></td><td><Badge c={c}/></td></tr>; })}{!rows.length && <tr><td colSpan={7}>No cases match your search or filters.</td></tr>}</tbody></table></div></>;
}
function CaseView({ c, config, users, personnelWritableKeys, busy, command, onDocument, onReason, onOpenWorkflow }: { c: M.Case; config: M.Config; users: Workspace['options']['users']; personnelWritableKeys: string[]; busy: boolean; command: (c: Command) => Promise<{ ok: boolean; error?: string }>; onDocument: (d: M.Document) => void; onReason: (type: 'cancel' | 'reopen') => void; onOpenWorkflow:(id:string)=>void }) {
  const actor=useContext(ActorContext);
  const note=(context:string,label:string)=><CaseNotes key={context} c={c} context={context} label={label} actor={actor} users={users} busy={busy} command={command}/>;
  const state = M.work(c), userName = (id: string | null) => users.find(u => u.id === id)?.name ?? 'Unassigned';
  return <><div className="v9-summary"><div><span className="v9-muted">Last working day</span><strong>{date(c.facts.lastDay)}</strong></div><div><span className="v9-muted">Case status</span><Badge c={c}/></div><div><span className="v9-muted">Overall progress</span><strong>{c.state==='pending'?'Not started':state.percent+'%'}</strong><span className="v9-muted">{c.state==='pending'?'Review the preview below':`${state.done} of ${state.total} done`}</span></div><div><span className="v9-muted">Access revoked by</span><strong>{date(c.revokeDate)}</strong></div></div>{c.review && <div className="v9-notice v9-warning" role="status"><strong>Needs HR review</strong><p>{c.review.detail}</p></div>}
  <div className="v9-columns"><div className="v9-stack"><section className="v9-panel"><div className="v9-heading"><h2>Offboarding case details</h2><div className="v9-actions">{['pending', 'submitted'].includes(c.state) && <Button danger onClick={() => onReason('cancel')}>Cancel case</Button>}{c.state === 'cleared' && <Button onClick={() => onReason('reopen')}>Reopen case</Button>}</div></div><OffboardingCaseForm key={`${c.id}:${c.revision}`} c={c} config={config} users={users} busy={busy} command={command}/></section>
    <CaseCalculator c={c} busy={busy} command={command}/>
    <section className="v9-panel v9-stack"><h2>Offboarding checklist</h2>{c.state === 'pending' ? <Field label="Checklist choice"><select value={c.override} onChange={e => command({ type: 'override', checklist: e.target.value })}><option value="automatic">Automatic matching</option><option value="none">No checklist (manual choice)</option>{config.checklists.filter(cl => cl.module === c.module).map(cl => <option key={cl.id} value={cl.id}>{cl.name}</option>)}</select></Field> : <p className="v9-muted">{c.checklistName}</p>}{c.state==='pending'?<ChecklistPreview c={c} config={config}/>:<><ul className="v9-list">{c.tasks.map(t => <li key={t.id}><div className="v9-heading"><div><strong>{t.name}</strong><div className="v9-muted">{userName(t.assignee)} · Due {date(t.dueOn)}{t.assignmentFailure ? ' · ' + t.assignmentFailure : ''}</div></div>{t.documentTemplate && <Button disabled={busy} onClick={() => { const d = M.activeDocument(c, t.documentTemplate!); if (d) onDocument(d); else command({ type: 'generate', template: t.documentTemplate! }); }}>Open document</Button>}<WorkAssignee name={t.name} group={t.group} assignee={t.assignee} config={config} users={users} busy={busy} editable={c.state === 'submitted' && !M.isResolved(t.status)} change={userId => command({type:'assign',id:t.id,userId})}/><CaseStatus name={t.name} kind="task" value={t.status} reason={t.reason} busy={busy} editable={c.state === 'submitted'} documentLinked={!!t.documentTemplate} change={(status, reason) => command({ type: 'task', id: t.id, status: status as M.Task['status'], reason })}/></div>{note(t.id,t.name)}</li>)}</ul>{!c.tasks.length && <p className="v9-muted">No checklist tasks.</p>}</>}</section>
    <section className="v9-panel"><h2>Return and revoke</h2><p className="v9-muted">Return items and access held by this employee.</p>{c.state === 'pending' ? <PendingReturns c={c} config={config} busy={busy} command={command}/> : <><ul className="v9-list">{c.items.map(i => <li key={i.id}><div className="v9-heading"><div><strong>{i.name}</strong><div className="v9-muted">{userName(i.assignee)} · Due {date(i.dueOn)}</div><div className="v9-muted">{i.nativeSource ? <Link className="v9-link" href={`/lifecycle/requisitions/onboarding/${i.nativeSource.caseId}`}>{i.nativeSource.requestNumber} · handed onboarding item</Link> : i.sourceId ? 'Issued asset register' : i.sourceCatalogueId ? 'Added by HR from the catalogue' : 'Case item'}{i.kind === 'system' && ' · HR records confirmed revocation'}</div>{i.returnReported&&i.status!=='done'&&<p className="v9-notice">Employee says this item was returned on {date(i.returnReported.at.slice(0,10))}{i.returnReported.note?' · '+i.returnReported.note:''}. Waiting for the providing team to confirm.</p>}</div><WorkAssignee name={i.name} group={i.group} assignee={i.assignee} config={config} users={users} busy={busy} editable={c.state === 'submitted' && !M.isResolved(i.status) && i.status !== 'notReturned'} change={userId => command({type:'assignItem',id:i.id,userId})}/><CaseStatus name={i.name} kind="item" value={i.status} reason={i.reason} busy={busy} editable={c.state === 'submitted'} change={(status, reason) => command({ type: 'item', id: i.id, status, reason })}/></div>{note(i.id,i.name)}</li>)}</ul>{!c.items.length && <p className="v9-muted">No return or revoke items recorded.</p>}</>}</section>
    <section className="v9-panel"><h2>Additional notes</h2>{note('case','this case')}</section>
    <CaseFiles key={c.id} c={c} config={config} readOnly/>
    <CaseWorkflows c={c} config={config} busy={busy} command={command} onOpenWorkflow={onOpenWorkflow}/>
    <section className="v9-panel"><h2>Documents and emails</h2><ul className="v9-list">{c.documents.map(d => <li key={d.id}><div className="v9-heading"><button className="v9-link" type="button" onClick={() => onDocument(d)}>{d.name}</button><span className="v9-badge">{d.status}</span>{M.canRegenerate(c,d) && <Button disabled={busy} onClick={() => command({type: 'documentRegenerate', id: d.id})}>Regenerate {d.name}</Button>}</div><span className="v9-muted">Version {d.version}</span></li>)}</ul><CaseMailHistory caseId={c.id} mails={c.mails} userName={userName} open={c.state === 'submitted'} busy={busy} command={command}/>{!c.documents.length && !c.mails.length && <p className="v9-muted">Documents and emails appear when their workflow runs.</p>}</section>
    <CaseEmails c={c} config={config} busy={busy} command={command}/>
    {c.pmChanges.length > 0 && <PersonnelReview key={c.id} c={c} busy={busy} writableKeys={personnelWritableKeys} command={command}/>}
    <section className="v9-panel"><h2>Exit clearance</h2>{c.state === 'pending' ? <p className="v9-muted">Submit this case to start its checklist and return/revoke work.</p> : c.state === 'cleared' ? <p>Cleared by {c.closedBy?.name} · {c.closedAt ? onboardingTimestamp(c.closedAt) : ''}{c.closeReason ? ' · ' + c.closeReason : ''}</p> : <p className="v9-muted">{state.open.length} tasks or items still open. {state.notReturned.length ? `${state.notReturned.length} items were not returned. HR must record how they were settled.` : ''}</p>}</section>
  </div><aside className="v9-stack"><section className="v9-panel"><h2>Progress by assignee</h2>{[...new Set(c.tasks.map(t => t.assignee))].map(id => { const tasks = c.tasks.filter(t => t.assignee === id); return <div key={id ?? 'unassigned'} style={{ marginBottom: 12 }}><strong>{userName(id)}</strong><div className="v9-muted">{tasks.filter(t => M.isResolved(t.status)).length} of {tasks.length} done</div></div>; })}</section><section className="v9-panel"><h2>Case log</h2><ul className="v9-list">{c.log.slice().reverse().map(log => <li key={log.id}><div>{log.detail}</div><div className="v9-muted">{log.actor.name} · {onboardingTimestamp(log.at)}</div></li>)}</ul></section></aside></div></>;
}
function NewCase({ employees, busy, close, submit, error }: { error: string; employees: Workspace['options']['employees']; busy: boolean; close: () => void; submit: (input: { employmentId: string; type: M.ExitType; noticeDate: string; lastDay: string }) => void }) {
  const [employee, setEmployee] = useState(''), [type, setType] = useState<M.ExitType>('Resignation'), [notice, setNotice] = useState(''), [last, setLast] = useState('');
  return <Dialog title="Start offboarding" close={close}><div className="v9-stack">{error && <p role="alert" className="v9-notice v9-error">{error}</p>}<div className="v9-fields"><Field label="Employee" required><select value={employee} onChange={e => setEmployee(e.target.value)}><option value="">Choose an employee…</option>{employees.map(e => <option key={e.id} value={e.id}>{e.name} · {e.employeeNo}</option>)}</select></Field><Field label="Case type" required><select value={type} onChange={e => setType(e.target.value as M.ExitType)}>{['Resignation', 'Termination', 'Contract end', 'Retirement', 'Non-confirmation'].map(t => <option key={t}>{t}</option>)}</select></Field><Field label="Notice date" required><OnboardingDateInput label="Notice date" value={notice} onChange={setNotice}/></Field><Field label="Last working day" required><OnboardingDateInput label="Last working day" value={last} onChange={setLast}/></Field></div>{['Termination', 'Non-confirmation'].includes(type) && <p className="v9-notice v9-warning">For this case type, review whether access must be revoked on a specific date.</p>}<div className="v9-actions"><Button primary disabled={busy || !employee || !M.validDate(notice) || !M.validDate(last)} onClick={() => submit({ employmentId: employee, type, noticeDate: notice, lastDay: last })}>Start offboarding</Button><Button onClick={close}>Cancel</Button></div></div></Dialog>;
}
function ModuleTabs({ module, setModule }: { module: M.Module; setModule: (m: M.Module) => void }) { return <div className="v9-actions" role="tablist" aria-label="Module">{(['onb', 'off'] as const).map(m => <button key={m} type="button" role="tab" aria-selected={module === m} className={'v9-button' + (module === m ? ' v9-button-primary' : '')} onClick={() => setModule(m)}>{m === 'onb' ? 'Onboarding' : 'Offboarding'}</button>)}</div>; }
type Edit = (fn: (n: M.Config) => void) => void;
export function ChecklistEditor({ config, module, selected, select, edit, editable, actor: suppliedActor, eligibleOwnerIds, users = [], candidates = [] }: { actor?: M.Actor; eligibleOwnerIds?: string[]; users?: Workspace['options']['users']; candidates?: ChecklistCandidate[]; config: M.Config; module: M.Module; selected: string; select: (id: string) => void; edit: Edit; editable: boolean }) {
  const contextActor = useContext(ActorContext), actor = suppliedActor ?? contextActor, labels = useContext(RuleLabels);
  const [deleting, setDeleting] = useState<string | null>(null), [changingOwner, setChangingOwner] = useState(false), [nextOwner, setNextOwner] = useState('');
  function create(source?: M.Checklist) { const id = crypto.randomUUID(); edit(next => { next.checklists.push(source ? { ...structuredClone(source), id, name: 'Copy of ' + source.name, ownerUserId: actor.id || undefined, createdAt: undefined, tasks: source.tasks.map(task => ({...structuredClone(task), id: crypto.randomUUID()})) } : { id, name: 'New checklist', module, ownerUserId: actor.id || undefined, rules: {}, tasks: [] }); }); select(id); setDeleting(null); setChangingOwner(false); }
  const lists = config.checklists.filter(c => c.module === module), current = lists.find(c => c.id === selected) ?? lists[0], index = config.checklists.findIndex(c => c.id === current?.id);
  if (!current) return <div className="v9-panel v9-stack"><p>No checklists.</p><Button disabled={!editable} onClick={() => create()}>New checklist</Button></div>;
  const owns = editable && (!current.ownerUserId || current.ownerUserId === actor.id);
  return <div className="v9-config-columns"><nav className="v9-panel v9-config-picker" aria-label="Checklists"><Button primary disabled={!editable} onClick={() => create()}>New checklist</Button>{[{name:'OWNED BY YOU',owned:true},{name:'OTHER CHECKLISTS',owned:false}].map(group => <section className="v9-stack" key={group.name}><h2>{group.name}</h2>{lists.filter(checklist => (checklist.ownerUserId === actor.id) === group.owned).map(cl => <button key={cl.id} type="button" aria-current={cl.id === current.id} onClick={() => { select(cl.id); setDeleting(null); setChangingOwner(false); }}><strong>{cl.name}</strong><span className="v9-badge">{cl.ownerUserId === actor.id ? 'Owner' : editable ? 'Can edit' : 'View only'}</span><span>{v9RulesSummary(cl.rules, labels)}</span><span>{cl.tasks.length} tasks · {checklistPopulation(config,cl,candidates).matching} matching people</span><span>Owner: {users.find(user => user.id === cl.ownerUserId)?.name ?? (cl.ownerUserId ? 'Unavailable owner' : 'Not assigned')}</span></button>)}</section>)}</nav><div className="v9-stack"><section className="v9-panel v9-stack"><div className="v9-heading"><Field label="Checklist name"><input className="v9-input" value={current.name} disabled={!editable} onChange={e => edit(n => { n.checklists[index].name = e.target.value; })}/></Field><Button disabled={!editable} onClick={() => create(current)}>Duplicate</Button></div><div className="v9-heading"><div><span className="v9-muted">Owner</span><p>{users.find(user => user.id === current.ownerUserId)?.name ?? (current.ownerUserId ? 'Unavailable owner' : 'Not assigned')}</p></div><div className="v9-actions"><Button disabled={!owns} onClick={() => { setNextOwner(current.ownerUserId ?? ''); setChangingOwner(true); }}>Change owner</Button></div></div>{changingOwner && <section className="v9-panel v9-stack" aria-label="Change checklist owner"><Field label="New owner"><select value={nextOwner} onChange={event => setNextOwner(event.target.value)}><option value="">Choose…</option>{users.filter(user => !eligibleOwnerIds || eligibleOwnerIds.includes(user.id)).map(user => <option key={user.id} value={user.id}>{user.name}</option>)}</select></Field><p className="v9-muted">The new owner needs existing configuration authority and access to this module.</p><div className="v9-actions"><Button primary disabled={!owns || !nextOwner} onClick={() => { edit(next => { next.checklists[index].ownerUserId = nextOwner; }); setChangingOwner(false); }}>Transfer ownership</Button><Button onClick={() => setChangingOwner(false)}>Cancel</Button></div></section>}<p className="v9-muted">{module === 'off' ? 'Day 0 is the last working day. Negative days are before it; positive days are after.' : 'Day 1 is the join date. Use negative days for tasks before joining.'}</p><RuleEditor module={module} rules={current.rules} change={rules => edit(n => { n.checklists[index].rules = rules; })} disabled={!editable}/><ChecklistPopulation config={config} checklist={current} candidates={candidates}/><h2>Tasks</h2><ChecklistBulkAssignment key={current.id} checklist={current} editable={editable} change={mode => edit(next => { const checklist=next.checklists.find(checklist=>checklist.id===current.id); if(checklist)for(const task of checklist.tasks)if(task.by==='group')task.mode=mode; })}/>{current.tasks.map((t, ti) => <div className="v9-panel v9-stack" key={t.id}><Field label="Task name"><input className="v9-input" value={t.name} disabled={!editable} onChange={e => edit(n => { n.checklists[index].tasks[ti].name = e.target.value; })}/></Field><div className="v9-fields"><Field label="Completed by"><select value={t.by} disabled={!editable} onChange={e => edit(n => { n.checklists[index].tasks[ti].by = e.target.value as M.TaskDefinition['by']; })}><option value="group">Assignment group</option><option value="manager">Line manager</option><option value="employee">{module === 'off' ? 'Leaver' : 'New joiner'}</option></select></Field><Field label="Assignment group"><select value={t.group ?? ''} disabled={!editable || t.by !== 'group'} onChange={e => edit(n => { n.checklists[index].tasks[ti].group = e.target.value || null; })}><option value="">Choose…</option>{config.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="Assignment"><select aria-label={`Assignment for ${t.name}`} value={t.mode} disabled={!editable || t.by !== 'group'} onChange={e => edit(n => { n.checklists[index].tasks[ti].mode = e.target.value as M.TaskDefinition['mode']; })}><option value="rr">Round robin</option><option value="manual">Manual</option></select></Field><label className="v9-actions"><input type="checkbox" aria-label={`Required: ${t.name}`} checked={t.required} disabled={!editable} onChange={e => edit(n => { n.checklists[index].tasks[ti].required = e.target.checked; })}/>Required</label><Field label="Opens on"><input className="v9-input" type="number" value={t.opens ?? ''} disabled={!editable} onChange={e => edit(n => { n.checklists[index].tasks[ti].opens = e.target.value === '' ? null : Number(e.target.value); })}/></Field><Field label="Due by"><input className="v9-input" type="number" value={t.due} disabled={!editable} onChange={e => edit(n => { n.checklists[index].tasks[ti].due = Number(e.target.value); })}/></Field><Field label="Document action"><select aria-label={`Document action for ${t.name}`} value={t.documentTemplate ? t.documentAction === 'completed' ? 'signed' : t.documentAction : ''} disabled={!editable} onChange={e => edit(n => { const task = n.checklists[index].tasks[ti], action = e.target.value; if (!action) { task.documentTemplate = null; return; } task.documentAction = action as 'signed' | 'sent'; const available = n.templates.filter(d => d.module === module && (action !== 'signed' || d.type !== 'Attachment')); if (!available.some(d => d.id === task.documentTemplate)) task.documentTemplate = available[0]?.id ?? null; })}><option value="">None</option><option value="signed">Document signed</option><option value="sent">Document sent</option></select></Field><Field label="Document"><select value={t.documentTemplate ?? ''} disabled={!editable} onChange={e => edit(n => { n.checklists[index].tasks[ti].documentTemplate = e.target.value || null; })}><option value="">None</option>{config.templates.filter(d => d.module === module && (t.documentAction === 'sent' || d.type !== 'Attachment')).map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></Field></div><div className="v9-actions"><Button disabled={!editable || ti === 0} onClick={() => edit(n => { const tasks = n.checklists[index].tasks; [tasks[ti - 1], tasks[ti]] = [tasks[ti], tasks[ti - 1]]; })}>Move up</Button><Button disabled={!editable || ti === current.tasks.length - 1} onClick={() => edit(n => { const tasks = n.checklists[index].tasks; [tasks[ti + 1], tasks[ti]] = [tasks[ti], tasks[ti + 1]]; })}>Move down</Button><Button disabled={!editable} danger onClick={() => edit(n => { n.checklists[index].tasks.splice(ti, 1); })}>Remove task</Button></div></div>)}<Button disabled={!editable} onClick={() => edit(n => { n.checklists[index].tasks.push({ id: crypto.randomUUID(), name: 'New task', by: 'group', group: config.peopleOpsGroup, mode: 'rr', opens: null, due: module === 'off' ? 0 : 1, required: false, documentTemplate: null, documentAction: 'signed' }); })}>Add task</Button></section><section className="v9-panel v9-stack" aria-label="Delete checklist"><h3>Delete checklist</h3><p className="v9-muted">Only the owner can delete this checklist. Pending cases use their next matching checklist; submitted snapshots are retained.</p>{deleting === current.id ? <div role="alertdialog" aria-label="Confirm checklist deletion" className="v9-notice v9-stack"><p>Delete “{current.name}”? This cannot be undone.</p><div className="v9-actions"><Button danger disabled={!owns} onClick={() => { edit(next => { next.checklists = next.checklists.filter(checklist => checklist.id !== current.id); }); select(''); setDeleting(null); }}>Confirm delete checklist</Button><Button onClick={() => setDeleting(null)}>Cancel</Button></div></div> : <Button danger disabled={!owns} onClick={() => setDeleting(current.id)}>Delete checklist</Button>}</section></div></div>;
}
function RuleEditor({ rules, change, disabled, module }: { module?: M.Module; rules: M.Rules; change: (rules: M.Rules) => void; disabled: boolean }) { const labels = useContext(RuleLabels); return <details><summary>Matching rules</summary><MatchingRules rules={rules} labels={labels} dimensions={module === 'onb' ? ['businessGroup', 'company', 'department', 'grade', 'employmentType'] : undefined} change={change} disabled={disabled}/></details>; }

function TemplateEditor({ users, config, selected, select, module, setModule, edit, editable, usage, references, saved }: { users: Workspace['options']['users']; references?: M.DefinitionUsage[]; usage?: M.TemplateUsage[]; saved: boolean; config: M.Config; selected: string; select: (id: string) => void; module: M.Module; setModule: (m: M.Module) => void; edit: Edit; editable: boolean }) {
  const actor = useContext(ActorContext), [importing, setImporting] = useState(false), [editing, setEditing] = useState(false), [menuOpen, setMenuOpen] = useState(false), [filter, setFilter] = useState<M.Module | 'all'>('all');
  const [kind, setKind] = useState<'document' | 'email'>('document'); const rows = (kind === 'document' ? config.templates : config.emails), current = rows.find(t => t.id === selected) ?? rows[0];
  const template = config.templates.find(t => kind === 'document' && t.id === current?.id), email = config.emails.find(t => kind === 'email' && t.id === current?.id), index = template ? config.templates.indexOf(template) : -1, emailIndex = email ? config.emails.indexOf(email) : -1;
  const version = template?.versions.find(v => v.state === 'draft') ?? (template ? M.currentVersion(template) : null), vi = template?.versions.indexOf(version!) ?? -1;
  function createDocument(type: M.Template['type']) { const template = newV9Template(type, actor, crypto.randomUUID(), new Date().toISOString()); edit(n => { n.templates.push(template); }); setFilter('all'); setModule('onb'); setKind('document'); select(template.id); setEditing(true); setMenuOpen(false); }
  function createEmail() { const email = newV9Email(crypto.randomUUID()); edit(n => { n.emails.push(email); }); setFilter('all'); setModule('onb'); setKind('email'); select(email.id); setEditing(true); }
  function open(kind: 'document' | 'email', id: string) { setKind(kind); select(id); setEditing(true); }
  function removeDefinition() {
    const id = current?.id; if (!id || !saved || !editable || definitionDeleteReason(config, kind, id, usage, references)) return;
    edit(next => {
      if (kind === 'email') next.emails = next.emails.filter(email => email.id !== id);
      else { next.templates = next.templates.filter(template => template.id !== id); for (const email of next.emails) { email.links = email.links.filter(templateId => templateId !== id); email.attachments = email.attachments.filter(templateId => templateId !== id); } }
    });
    setEditing(false); select('');
  }
  const documents = config.templates.filter(t => filter === 'all' || t.module === filter), emails = config.emails.filter(t => filter === 'all' || t.module === filter);
  return <div className="v9-stack"><div className="v9-actions" role="tablist" aria-label="Module">{(['all', 'onb', 'off'] as const).map(value => <button key={value} type="button" role="tab" aria-selected={filter === value} className={'v9-button' + (filter === value ? ' v9-button-primary' : '')} onClick={() => { setFilter(value); if (value !== 'all') setModule(value); }}>{value === 'all' ? 'All modules' : value === 'onb' ? 'Onboarding' : 'Offboarding'}</button>)}</div>
    <section className="v9-panel v9-stack v9-template-list" aria-label="Document templates"><header className="v9-heading"><div><h2>Document templates</h2><p className="v9-muted">Forms, acknowledgements, letters and generated attachments.</p></div><div className="v9-template-new"><Button disabled={!editable} onClick={() => setMenuOpen(value => !value)}>New template</Button>{menuOpen && <div className="v9-template-menu" role="menu" aria-label="New template type">{(['Form', 'Acknowledgement', 'Letter', 'Attachment'] as const).map(type => <button key={type} type="button" role="menuitem" disabled={!editable} onClick={() => createDocument(type)}>{type}</button>)}<button type="button" role="menuitem" disabled={!editable} onClick={() => { setMenuOpen(false); setImporting(true); }}>Import from a file</button></div>}</div></header>
      {!documents.length && <p className="v9-muted">No document templates for this module yet.</p>}<ul className="v9-list v9-template-rows">{documents.map(t => <li key={t.id}><button type="button" className="v9-template-name" onClick={() => open('document', t.id)}><strong>{t.name}</strong><span className="v9-muted">{t.module === 'onb' ? 'Onboarding' : 'Offboarding'} · {Object.values(t.rules).some(values => values?.length) ? 'Matching rules apply' : 'Everyone in the module'}</span></button><span className="v9-badge">{t.module === 'onb' ? 'Onboarding' : 'Offboarding'}</span><span className={'v9-badge v9-template-' + t.type.toLowerCase()}>{t.type}</span><span className="v9-badge">{t.retired ? 'Retired · ' : ''}{M.currentVersion(t) ? `v${M.currentVersion(t)!.version} in use${t.versions.some(v => v.state === 'draft') ? ' · draft v' + t.versions.find(v => v.state === 'draft')!.version : ''}` : 'Draft'}</span><button type="button" className="v9-button" aria-label={`Edit ${t.name}`} onClick={() => open('document', t.id)}>Edit</button></li>)}</ul>
    </section>
    <section className="v9-panel v9-stack v9-template-list" aria-label="Email templates"><header className="v9-heading"><div><h2>Email templates</h2><p className="v9-muted">The words, attachments and documents. A workflow decides when it is sent.</p></div><Button disabled={!editable} onClick={createEmail}>New email</Button></header>{!emails.length && <p className="v9-muted">No email templates for this module yet.</p>}<ul className="v9-list v9-template-rows">{emails.map(t => <li key={t.id}><button type="button" className="v9-template-name" onClick={() => open('email', t.id)}><strong>{t.name}</strong><span className="v9-muted">{t.attachments.length} PDFs · {t.links.length} links · {t.slots.length + (t.files?.length ?? 0)} files</span></button><span className="v9-badge">{t.module === 'onb' ? 'Onboarding' : 'Offboarding'}</span><span className={'v9-badge' + (t.active ? ' v9-badge-green' : '')}>{t.active ? 'Active' : 'Inactive'}</span><button type="button" className="v9-button" aria-label={`Edit ${t.name}`} onClick={() => open('email', t.id)}>Edit</button></li>)}</ul></section>
    {importing && <TemplateImportDialog module={module} actor={actor} close={() => setImporting(false)} create={template => { edit(n => { n.templates.push(template); }); setFilter('all'); setModule(template.module); open('document', template.id); }}/>}
    {editing && current && <TemplateSurface kind={kind} close={() => setEditing(false)} heading={email ? <input className="v9-input v9-email-title" aria-label="Email name" maxLength={200} value={email.name} disabled={!editable} onChange={event => edit(n => { n.emails[emailIndex].name = event.target.value; })}/> : undefined}><div className="v9-panel v9-stack">{template && version && <><h2>{template.name}</h2><Field label="Template name"><input className="v9-input" maxLength={200} value={template.name} disabled={!editable} onChange={e => edit(n => { n.templates[index].name = e.target.value; })}/></Field><Field label="Module"><select value={template.module} disabled={!editable} onChange={e => { const module = e.target.value as M.Module; edit(n => { n.templates[index].module = module; }); setModule(module); }}><option value="onb">Onboarding</option><option value="off">Offboarding</option></select></Field><label className="v9-actions"><input type="checkbox" checked={template.retired} disabled={!editable} onChange={e => edit(n => { n.templates[index].retired = e.target.checked; })}/>Retired</label><RuleEditor module={template.module} rules={template.rules} disabled={!editable} change={rules => edit(n => { n.templates[index].rules = rules; })}/>{template.note && <p className="v9-muted">{template.note}</p>}<p className="v9-muted">Version {version.version} · {version.state}</p><div className="v9-actions"><Button disabled={!editable || version.state === 'draft'} onClick={() => edit(n => { const v = structuredClone(version); v.version = Math.max(...template.versions.map(v => v.version)) + 1; v.state = 'draft'; n.templates[index].versions.push(v); })}>New draft version</Button><Button primary disabled={!editable || version.state !== 'draft'} onClick={() => edit(n => { n.templates[index].versions[vi].state = 'published'; n.templates[index].currentVersion = version.version; })}>Publish version</Button></div><Field label="HR signature"><select value={template.hrStep} disabled={!editable || version.state !== 'draft' || template.type === 'Attachment'} onChange={e => edit(n => { n.templates[index].hrStep = e.target.value as M.Template['hrStep']; })}><option value="none">No HR signature</option><option value="before">HR signs before employee</option><option value="after">HR countersigns</option></select></Field><TemplateVersionHistory template={template} usage={usage} editable={editable} saved={saved} useVersion={version => edit(n => { const selected = n.templates[index].versions.find(item => item.version === version)!; selected.state = 'published'; n.templates[index].currentVersion = version; })} remove={version => edit(n => { n.templates[index].versions = n.templates[index].versions.filter(item => item.version !== version); })}/><TemplateVersionEditor version={version} name={template.name} disabled={!editable || version.state !== 'draft'} change={change => edit(n => { change(n.templates[index].versions[vi]); })}/></>}{email && <EmailDefinition groups={config.groups} users={users} email={email} revision={config.revision} uploadsReady={saved} hideName selectModule={setModule} templates={config.templates} disabled={!editable} change={update => edit(n => { update(n.emails[emailIndex]); })}/>}<DefinitionDelete key={`${kind}:${current.id}`} kind={kind} name={current.name} reason={definitionDeleteReason(config, kind, current.id, usage, references)} saved={saved} editable={editable} remove={removeDefinition}/></div></TemplateSurface>}
  </div>;
}
function TemplateSurface({ kind, close, children, heading }: { heading?: ReactNode; kind: 'document' | 'email'; close: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { ref.current?.showModal(); return () => ref.current?.close(); }, []);
  return <dialog ref={ref} className={'v9-dialog v9-template-surface ' + (kind === 'email' ? 'v9-email-drawer' : 'v9-template-screen')} aria-label={kind === 'email' ? 'Edit email template' : 'Edit document template'} onCancel={close}><div className="v9-template-surface-content"><header className="v9-heading"><>{heading ?? <h2>Edit document template</h2>}</><button type="button" className="v9-button" aria-label={kind === 'email' ? 'Close' : 'Back to templates'} onClick={close}>{kind === 'email' ? <X size={16}/> : 'Back to templates'}</button></header>{children}</div></dialog>;
}
